-- Read-only checks. Resolve business exceptions before enabling the paired application release.
select 'legacy_count_needs_recount' issue,id,d->>'no' document,d->>'status' status from jxc_docs where k='counts' and d->>'status' in ('pending','fin_ok') and not coalesce((d->>'integritySnapshot')::boolean,false);
select 'duplicate_product_lines' issue,k,id,d->>'no' document,d->>'status' status from jxc_docs where k in ('so','po') and d->>'status' not in ('draft','cancel','rejected') and (select count(*) from jsonb_array_elements(d->'items'))<>(select count(distinct i->>'pid') from jsonb_array_elements(d->'items') i);
select 'missing_credit_configuration' issue,s.id,s.d->>'no' document,s.d->>'cus' customer from jxc_docs s left join jxc_docs p on p.k='partners' and p.id=s.d->>'cus' where s.k='so' and s.d->>'pay'='credit' and s.d->>'status' in ('submitted','credit_gm','approved') and (p.d->>'creditLimit' is null or (p.d->>'creditLimit')::numeric<=0 or p.d->>'paymentDays' is null);
select 'unlinked_money' issue,f.id,f.d->>'ref' reference from jxc_docs f where f.k='fin' and coalesce(f.d->>'refKind','so') in ('so','po') and f.d->>'status' not in ('void','rejected') and not exists(select 1 from jxc_docs s where s.k=coalesce(f.d->>'refKind','so') and s.id=f.d->>'ref');
select 'purchase_counter_differs_from_ledger' issue,p.id,p.d->>'no' document,i->>'pid' product,i->>'recv' declared_received,(select coalesce(sum((m.d->>'qty')::numeric),0) from jxc_docs m join jxc_docs g on g.k='grn' and g.id=m.d->>'ref' where m.k='moves' and m.d->>'type'='po_in' and g.d->>'po'=p.id and m.d->>'pid'=i->>'pid') ledger_received from jxc_docs p cross join lateral jsonb_array_elements(p.d->'items') i where p.k='po' and p.d->>'status' not in ('draft','cancel') and coalesce((i->>'recv')::numeric,0)<>(select coalesce(sum((m.d->>'qty')::numeric),0) from jxc_docs m join jxc_docs g on g.k='grn' and g.id=m.d->>'ref' where m.k='moves' and m.d->>'type'='po_in' and g.d->>'po'=p.id and m.d->>'pid'=i->>'pid');
select k,count(*) legacy_documents_without_currency from jxc_docs where k in ('po','so','fin','refund','exp') and not (d ? 'currency') group by k;
select pg_size_pretty(pg_total_relation_size('public.jxc_docs')) current_document_table_size;
